    return false;
  } catch (e) {
    console.log('PASS: Constructor correctly rejects zero capacity');
  }
  
  try {
    new Cache(1.5);
    console.log('FAIL: Constructor should throw for non-integer capacity');
    return false;
  } catch (e) {
    console.log('PASS: Constructor correctly rejects non-integer capacity');
