  try {
    const cache = new Cache(2);
    console.log('PASS: Constructor accepts valid capacity');
  } catch (e) {
    console.log('FAIL: Constructor should accept valid capacity');
    return false;
  }
  
  // Test 2: Basic set and get
  const cache = new Cache(2);
  
  cache.set('a', 1);
  cache.set('b', 2);
  
  if (cache.get('a') === 1) {
    console.log('PASS: Basic get works');
  } else {
