console.log(evaluate('7.5 / 2.5')); // Should be 3

// Test error cases
try {
    evaluate('5 / 0');
    console.log('ERROR: Should have thrown division by zero');
} catch (e) {
    console.log('Correctly caught division by zero error');
}

try {
