// Library class implementation
class Library {
  constructor() {
    this.books = new Map();
    this.checkedOut = new Map(); // Track which member has which book
  }
  
  addBook(isbn, title, copies = 1) {
    // Validate copies parameter
    if (!Number.isInteger(copies) || copies <= 0) {
      throw new Error("copies must be a positive integer");
    }
    
    // If ISBN already exists, add to existing copies
    if (this.books.has(isbn)) {
      const existingBook = this.books.get(isbn);
      existingBook.copies += copies;
    } else {
      // Add new book
      this.books.set(isbn, { title, copies });
    }
  }
  
  copies(isbn) {
    const book = this.books.get(isbn);
    return book ? book.copies : 0;
  }
  
  titles() {
    // Get all titles and sort alphabetically
    const titles = Array.from(this.books.values()).map(book => book.title);
    return titles.sort();
  }
  
  available(isbn) {
    const book = this.books.get(isbn);
    if (!book) return 0;
    
    // Count how many copies are currently checked out
    let checkedOutCount = 0;
    for (const [member, books] of this.checkedOut.entries()) {
      if (books.has(isbn)) {
        checkedOutCount += books.get(isbn) || 0;
      }
    }
    return book.copies - checkedOutCount;
  }
  
  checkout(isbn, member) {
    // Validate ISBN exists
    const book = this.books.get(isbn);
    if (!book) {
      throw new Error(`Book with ISBN ${isbn} not found`);
    }
    
    // Check if any copies are available
    if (this.available(isbn) <= 0) {
      throw new Error(`No copies of book ${isbn} available`);
    }
    
    // Check if member already has this book
    if (this.checkedOut.has(member)) {
      const memberBooks = this.checkedOut.get(member);
      if (memberBooks.has(isbn)) {
        throw new Error(`Member ${member} already has book ${isbn}`);
      }
    }
    
    // Perform checkout
    if (!this.checkedOut.has(member)) {
      this.checkedOut.set(member, new Map());
    }
    const memberBooks = this.checkedOut.get(member);
    if (memberBooks.has(isbn)) {
      memberBooks.set(isbn, memberBooks.get(isbn) + 1);
    } else {
      memberBooks.set(isbn, 1);
    }
  }
}

// Export the Library class
module.exports = { Library };
// Add asserts to test the Library class
const assert = require('assert');

// Test 1: Add a book and check copies
const library = new Library();
library.addBook("978-0134685991", "Effective Java", 3);
assert.strictEqual(library.copies("978-0134685991"), 3);

// Test 2: Add more copies of existing book
library.addBook("978-0134685991", "Effective Java", 2);
assert.strictEqual(library.copies("978-0134685991"), 5);

// Test 3: Add a new book with different ISBN
library.addBook("978-0596009205", "Head First Design Patterns", 1);
assert.strictEqual(library.copies("978-0596009205"), 1);

// Test 4: Check copies for unknown ISBN
assert.strictEqual(library.copies("unknown"), 0);

// Test 5: Test titles() method
const titles = library.titles();
assert.deepStrictEqual(titles, ["Effective Java", "Head First Design Patterns"]);

// Test 6: Add book with same ISBN but different title (should keep first title)
library.addBook("978-0134685991", "Effective Java Second Edition", 1);
assert.strictEqual(library.copies("978-0134685991"), 6);
assert.strictEqual(library.titles()[0], "Effective Java"); // Should still be first title

// Test 7: Test error for invalid copies parameter
assert.throws(() => {
  library.addBook("978-1234567890", "Test Book", 0);
}, Error);

assert.throws(() => {
  library.addBook("978-1234567890", "Test Book", -1);
}, Error);

assert.throws(() => {
  library.addBook("978-1234567890", "Test Book", 1.5);
}, Error);

console.log("All asserts passed!");

// Test 8: Test available method
assert.strictEqual(library.available("978-0134685991"), 6);
assert.strictEqual(library.available("978-0596009205"), 1);
assert.strictEqual(library.available("unknown"), 0);

// Test 9: Test checkout method
library.checkout("978-0134685991", "Alice");
assert.strictEqual(library.available("978-0134685991"), 5);

// Test 10: Test checkout with unavailable book
assert.throws(() => {
  library.checkout("978-0134685991", "Bob"); // Should work since 4 available
}, Error);

// Test 11: Test checkout with unknown ISBN
assert.throws(() => {
  library.checkout("unknown", "Charlie");
}, Error);

// Test 12: Test checkout with member who already has the book
library.checkout("978-0596009205", "Alice");
assert.throws(() => {
  library.checkout("978-0596009205", "Alice"); // Should fail - Alice already has it
}, Error);

console.log("All new tests passed!");

