assert.strictEqual(library.copies("978-0596009205"), 1);

// Test 4: Check copies for unknown ISBN
assert.strictEqual(library.copies("unknown"), 0);

// Test 5: Test titles() method
const titles = library.titles();
assert.deepStrictEqual(titles, ["Effective Java", "Head First Design Patterns"]);

// Test 6: Add book with same ISBN but different title (should keep first title)
library.addBook("978-0134685991", "Effective Java Second Edition", 1);
assert.strictEqual(library.copies("978-0134685991"), 6);
assert.strictEqual(library.titles()[0], "Effective Java"); // Should still be first title

// Test 7: Test error for invalid copies parameter
assert.throws(() => {
